 const [register,setRegister]=useState(false),[stage,setStage]=useState('password'),[email,setEmail]=useState(''),[name,setName]=useState(''),[password,setPassword]=useState(''),[setupCode,setSetupCode]=useState(''),[show,setShow]=useState(false),[code,setCode]=useState(''),[recovery,setRecovery]=useState(false),[qr,setQr]=useState(''),[secret,setSecret]=useState(''),[codes,setCodes]=useState<string[]>([]),[pending,setPending]=useState<User|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);
