function download(filename:string,contents:string){const url=URL.createObjectURL(new Blob([contents],{type:filename.endsWith('.csv')?'text/csv;charset=utf-8':'text/plain'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows:(string|number)[][]){return rows.map(row=>row.map(x=>'"'+String(x).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\n')}
